python3 << 'EOF'
import yaml

with open('/home/ubuntu/.agent-ml-research-idea_gen_0514_1/projects/struct_self_consist_ie/registry.yaml', 'r') as f:
    data = yaml.safe_load(f)

# Extract detailed GPU allocations with experiments
print("DETAILED GPU ALLOCATION BY SERVER AND EXPERIMENT:")
print("=" * 80)

servers = {}
for exp_id, exp_data in data.get('experiments', {}).items():
    spec = exp_data.get('spec', {})
    server = spec.get('server') or exp_data.get('server', 'unknown')
    gpu_ids = spec.get('gpu_ids', [])
    gpu_str = exp_data.get('gpu', None)

    if gpu_ids or gpu_str or server:
        if server not in servers:
            servers[server] = []
        servers[server].append({
            'exp_id': exp_id,
            'gpu_ids': gpu_ids,
            'gpu_str': gpu_str,
            'status': exp_data.get('status', 'unknown')
        })

for server in sorted(servers.keys()):
    print(f"\n{'='*80}")
    print(f"SERVER: {server}")
    print(f"{'='*80}")

    gpu_allocations = {}
    for item in servers[server]:
        gpu_ids = item['gpu_ids'] if item['gpu_ids'] else []
        gpu_str = item['gpu_str']

        if gpu_ids:
            key = str(sorted(gpu_ids))
        elif gpu_str:
            key = gpu_str
        else:
            key = 'not_specified'

        if key not in gpu_allocations:
            gpu_allocations[key] = []
        gpu_allocations[key].append(item['exp_id'])

    for gpu_config in sorted(gpu_allocations.keys()):
        exps = gpu_allocations[gpu_config]
        print(f"\n  GPU Config: {gpu_config}")
        print(f"  Experiments ({len(exps)}): {', '.join(exps[:5])}", end='')
        if len(exps) > 5:
            print(f" ... and {len(exps)-5} more")
        else:
            print()

EOF

